/// <summary>
/// AVA Stephan Schneider 11.10.21
/// </summary>
class NDX_KBVJobs extends RunBaseBatch
{
    DialogField                     dlgKBVPeriodicUpdate;
    DialogField                     dlgKBVPeriodicUpdateGLB;
    DialogField                     dlgKBVUpdatePotSalesVol;
    DialogField                     dlgKBVUpdatePotSalesVolGLB;
    DialogField                     dlgKBVSetResponsibilities;
    DialogField                     dlgKBVActivitySendList;
    DialogField                     dlgKCS_PrintMasterDataList;
    DialogField                     dlgKBVBuildingProjectId;

    KBVPeriodicUpdate               kBVPeriodicUpdate;
    KBVPeriodicUpdateGLB            kBVPeriodicUpdateGLB;
    KBVUpdatePotSalesVol            kBVUpdatePotSalesVol;
    KBVUpdatePotSalesVolGLB         kBVUpdatePotSalesVolGLB;
    KBVSetResponsibilities          kBVSetResponsibilities;
    KBVActivitySendList             kBVActivitySendList;
    KCS_PrintMasterDataList         printMasterDataList;
    KCS_KBVBuildingProjectID        kBVBuildingProjectId;

    boolean                         lCalledFromKBV;
    boolean                         lJobMode;

    #define.CurrentVersion(2)
    #define.Version1(1)
    #localmacro.CurrentList
    KBVPeriodicUpdate,
    KBVPeriodicUpdateGLB,
    KBVUpdatePotSalesVol,
    kbvUpdatePotSalesVolGLB,
    KBVSetResponsibilities,
    KBVActivitySendList,
    //kBVBuildingProjectId,
    printMasterDataList
    #endmacro

}

Method.Source:
public Object dialog()
{
    DialogRunbase   dialog = super();

    dialog.addGroup("@NDX:NXAFilterSettings");    //Filtereinstellungen
    dlgKBVBuildingProjectId         = dialog.addFieldValue(extendedtypestr(KCS_KBVBuildingProjectId), kBVBuildingProjectId);
    if(lCalledFromKBV)
    {
        dlgKBVBuildingProjectId.enabled(false);
    }

    dialog.addGroup("@SYS80127");   //Status
    dlgKBVPeriodicUpdate            = dialog.addFieldValue(extendedtypestr(kBVPeriodicUpdate), kBVPeriodicUpdate);
    dlgKBVPeriodicUpdateGLB         = dialog.addFieldValue(extendedtypestr(kBVPeriodicUpdateGLB), kBVPeriodicUpdateGLB);

    dialog.addGroup("@NDX:NXAPotentialSalesVolume");     //Umsatzpotential
    dlgKBVUpdatePotSalesVol         = dialog.addFieldValue(extendedtypestr(kBVUpdatePotSalesVol), kBVUpdatePotSalesVol);
    dlgKBVUpdatePotSalesVolGLB      = dialog.addFieldValue(extendedtypestr(kBVUpdatePotSalesVolGLB), kBVUpdatePotSalesVolGLB);

    dialog.addGroup("@NDX:NXAResponsibilities");     //Zuständigkeiten
    dlgKBVSetResponsibilities       = dialog.addFieldValue(extendedtypestr(kBVSetResponsibilities), kBVSetResponsibilities);

    dialog.addGroup("@NDX:NXAActions");    //Aktivitäten
    dlgKBVActivitySendList          = dialog.addFieldValue(extendedtypestr(kBVActivitySendList), kBVActivitySendList);
    dlgKCS_PrintMasterDataList      = dialog.addFieldValue(extendedtypestr(KCS_PrintMasterDataList), printMasterDataList);

    return dialog;
}

public boolean getFromDialog()
{
    kBVPeriodicUpdate           = dlgKBVPeriodicUpdate.value();
    kBVPeriodicUpdateGLB        = dlgKBVPeriodicUpdateGLB.value();
    kBVUpdatePotSalesVol        = dlgKBVUpdatePotSalesVol.value();
    kBVUpdatePotSalesVolGLB     = dlgKBVUpdatePotSalesVolGLB.value();
    kBVSetResponsibilities      = dlgKBVSetResponsibilities.value();
    kBVActivitySendList         = dlgKBVActivitySendList.value();
    printMasterDataList         = dlgKCS_PrintMasterDataList.value();
    kBVBuildingProjectId        = dlgKBVBuildingProjectId.value();

    return super();
}

protected void new()
{
    super();

    lJobMode        = false;
    lCalledFromKBV  = false;
}

public KCS_KBVBuildingProjectId parmkcs_KBVBuildingProjectId(KCS_KBVBuildingProjectId _kcs_KBVBuildingProjectId = kBVBuildingProjectId)
{
    kBVBuildingProjectId = _kcs_KBVBuildingProjectId;

    return kBVBuildingProjectId;
}

public boolean parmlCalledFromKBV(boolean l_lCalledFromKBV = lCalledFromKBV)
{
    lCalledFromKBV = l_lCalledFromKBV;

    return lCalledFromKBV;
}

public boolean parmlJobMode(boolean l_lJobMode = lJobMode)
{
    lJobMode = l_lJobMode;

    return lJobMode;
}

public void run()
{
    timeofDay   time;

    //Start
    time = DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone());
    info(strfmt("@NDX:NXAStartTimeP1", time2str(time, TimeSeparator::Colon, TimeFormat::Auto)));

    //Ende
    info(strfmt("@NDX:NXAEndTimeP1", time2str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone()), TimeSeparator::Colon, TimeFormat::Auto)));
}

public boolean unpack(container packedClass)
{
    Version version = RunBase::getVersion(packedClass);

    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList] = packedClass;
            break;
        default:
            return false;
    }

    return true;
}

server static NDX_KBVJobs construct()
{
    return new NDX_KBVJobs();
}

static void main(Args args)
{
    NDX_KBVJobs                 nDX_KBVJobs;
    KCS_KBVBuildingProjectTable kCS_KBVBuildingProjectTable;

    nDX_KBVJobs = NDX_KBVJobs::construct();

    if (args.dataset() && args.dataset() == tablenum(KCS_KBVBuildingProjectTable))
    {
        kCS_KBVBuildingProjectTable = args.record();
        if(kCS_KBVBuildingProjectTable.RecId)
        {
            nDX_KBVJobs.parmkcs_KBVBuildingProjectId(kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);
            nDX_KBVJobs.parmlCalledFromKBV(true);
        }
    }

    if (nDX_KBVJobs.prompt())
    {
        nDX_KBVJobs.runOperation();
        if(nDX_KBVJobs.parmlCalledFromKBV())
        {
            args.caller().NDX_RereadBVJobDataSource();
        }
    }


}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>boolean</returns>
protected boolean canRunInNewSession()
{
    return false;
}
